import React, { useState, useEffect } from 'react';
import './App.css';

function App() {
  const [products, setProducts] = useState([]);
  const [cart, setCart] = useState([]);
  const [loading, setLoading] = useState(true);

  // API 端点 - 直接调用后端服务
  // API endpoints - directly call backend services
  const PRODUCT_API = 'http://localhost:5001/api/products';
  const ORDER_API = 'http://localhost:5002/api/orders';

  useEffect(() => {
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    try {
      const response = await fetch(PRODUCT_API);
      const data = await response.json();
      setProducts(data);
      setLoading(false);
    } catch (error) {
      console.error('Error fetching products:', error);
      setLoading(false);
      alert('无法加载产品。请确保 Product Service (端口 5001) 正在运行。\nCannot load products. Make sure Product Service (port 5001) is running.');
    }
  };

  const addToCart = (product) => {
    setCart([...cart, product]);
  };

  const placeOrder = async () => {
    if (cart.length === 0) {
      alert('购物车是空的！\nCart is empty!');
      return;
    }

    try {
      const total = cart.reduce((sum, item) => sum + parseFloat(item.price), 0);

      const order = {
        customer_email: 'customer@example.com',
        total_amount: total,
        items: cart.map(item => ({
          product_id: item.id,
          quantity: 1,
          price: parseFloat(item.price)
        }))
      };

      const response = await fetch(ORDER_API, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(order)
      });

      if (response.ok) {
        const data = await response.json();
        alert(`订单创建成功！订单号: ${data.order_id}\nOrder placed successfully! Order ID: ${data.order_id}`);
        setCart([]);
      } else {
        alert('订单创建失败\nFailed to create order');
      }
    } catch (error) {
      console.error('Error placing order:', error);
      alert('无法创建订单。请确保 Order Service (端口 5002) 正在运行。\nCannot create order. Make sure Order Service (port 5002) is running.');
    }
  };

  if (loading) {
    return (
      <div className="App">
        <header>
          <h1>E-Commerce Demo</h1>
        </header>
        <div className="loading">加载中... / Loading...</div>
      </div>
    );
  }

  return (
    <div className="App">
      <header>
        <h1>E-Commerce Demo</h1>
        <div className="cart-badge">购物车 / Cart: {cart.length}</div>
      </header>

      <main>
        <section className="products">
          <h2>产品列表 / Products</h2>
          <div className="product-grid">
            {products.length > 0 ? (
              products.map(product => (
                <div key={product.id} className="product-card">
                  <h3>{product.name}</h3>
                  <p>{product.description}</p>
                  <p className="price">${parseFloat(product.price).toFixed(2)}</p>
                  <p>库存 / Stock: {product.stock}</p>
                  <button onClick={() => addToCart(product)}>
                    加入购物车 / Add to Cart
                  </button>
                </div>
              ))
            ) : (
              <p>没有可用产品 / No products available</p>
            )}
          </div>
        </section>

        {cart.length > 0 && (
          <section className="cart">
            <h2>购物车 / Shopping Cart</h2>
            <ul>
              {cart.map((item, idx) => (
                <li key={idx}>
                  {item.name} - ${parseFloat(item.price).toFixed(2)}
                </li>
              ))}
            </ul>
            <p>
              总计 / Total: ${cart.reduce((sum, item) => sum + parseFloat(item.price), 0).toFixed(2)}
            </p>
            <button onClick={placeOrder}>下单 / Place Order</button>
          </section>
        )}
      </main>

      <footer style={{
        textAlign: 'center',
        padding: '20px',
        color: '#666',
        marginTop: '40px',
        borderTop: '1px solid #eee'
      }}>
        <p>🔗 API 连接状态 / API Connection Status:</p>
        <p style={{ fontSize: '0.9em' }}>
          Product Service: http://localhost:5001 | 
          Order Service: http://localhost:5002
        </p>
      </footer>
    </div>
  );
}

export default App;
